export type ImageSize = '1K' | '2K' | '4K';

export type LightingStyle = 
  | 'Studio Softbox' 
  | 'High-Key Cinematic' 
  | 'Dramatic Rim Light' 
  | 'Natural Sunlight' 
  | 'Neon Cyberpunk';

export type CameraPerspective = 
  | 'Eye Level' 
  | 'Low Angle' 
  | 'Close-Up Portrait' 
  | 'Full Body Shot' 
  | 'Over-the-shoulder';

export type Gender = 'Female' | 'Male' | 'Non-binary';

export type BodyShape = 
  | 'Slim' 
  | 'Athletic' 
  | 'Curvy' 
  | 'Muscular' 
  | 'Plus Size'
  | 'Standard';

export interface ModelConfig {
  aspectRatio: AspectRatio;
  imageSize: ImageSize;
  lighting: LightingStyle;
  perspective: CameraPerspective;
  gender: Gender;
  bodyShape: BodyShape;
}

export interface UploadedImage {
  id: string;
  url: string;
  base64: string;
  mimeType: string;
}

export interface GenerationResult {
  imageUrl: string;
  prompt: string;
}

export interface HistoryItem extends GenerationResult {
  id: string;
  timestamp: number;
}

import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { ModelConfig, UploadedImage } from "./types";

export const generateModelImage = async (
  images: UploadedImage[],
  config: ModelConfig,
  customPrompt: string
): Promise<{ imageUrl: string }> => {
  // Always create a new instance to ensure we use the most up-to-date API key
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

  // Prepare image parts for the multimodal request
  const imageParts = images.map(img => ({
    inlineData: {
      mimeType: img.mimeType,
      data: img.base64.split(',')[1], // Strip data:image/png;base64,
    },
  }));

  // Core behavioral instructions for the subject extraction and background
  const systemInstruction = `ACT AS AN EXPERT STUDIO PHOTOGRAPHER. 
  YOUR TASK: Generate a NEW professional studio photograph.
  SUBJECT EXTRACTION: Study the provided reference photos. Extract the facial features, character traits, and unique physical identity of the subject. Replicate this identity perfectly in the generated image.
  ENVIRONMENT: The background MUST BE PURE WHITE (#FFFFFF), perfectly clean, with no shadows or gradient transitions.
  TECHNICAL REQUIREMENTS: Ultra-realistic, 8k resolution, highly detailed skin texture, micro-expressions, professional studio lighting.
  OUTPUT: You MUST return an image. Do not return text descriptions unless you are unable to fulfill the request due to safety policies.`;

  // Specific configuration prompt
  const userPrompt = `Generate a photograph of the subject with the following characteristics:
  - Gender: ${config.gender}
  - Body Type: ${config.bodyShape}
  - Camera Perspective: ${config.perspective}
  - Lighting Style: ${config.lighting}

  Detailed Scene: ${customPrompt}`;

  try {
    const response: GenerateContentResponse = await ai.models.generateContent({
      model: 'gemini-3-pro-image-preview',
      contents: {
        parts: [
          ...imageParts,
          { text: userPrompt }
        ]
      },
      config: {
        systemInstruction,
        imageConfig: {
          aspectRatio: config.aspectRatio,
          imageSize: config.imageSize,
        },
      },
    });

    let refusalText = "";

    // Find the image part in candidates
    const parts = response.candidates?.[0]?.content?.parts || [];
    for (const part of parts) {
      if (part.inlineData) {
        return {
          imageUrl: `data:image/png;base64,${part.inlineData.data}`,
        };
      }
      if (part.text) {
        refusalText += part.text;
      }
    }

    // If we reached here, no image was found. If the model provided text, use it as the error message.
    if (refusalText) {
      throw new Error(`Model Refusal: ${refusalText}`);
    }

    throw new Error('The model did not generate an image and provided no explanation.');
  } catch (error: any) {
    console.error('Gemini Generation Error:', error);

    // Reset key selection if the specific error occurs
    if (error.message?.includes("Requested entity was not found.")) {
      throw new Error("API_KEY_RESET");
    }

    throw error;
  }
};

import React, { useState, useEffect } from 'react';
