  interface Window {
    aistudio: any;
  }
}

const App: React.FC = () => {
  const [images, setImages] = useState<UploadedImage[]>([]);
  const [config, setConfig] = useState<ModelConfig>({
    aspectRatio: '1:1',
    imageSize: '1K',
    lighting: 'Studio Softbox',
    perspective: 'Eye Level',
    gender: 'Female',
    bodyShape: 'Standard'
  });
  const [generatedPrompt, setGeneratedPrompt] = useState('');
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<GenerationResult | null>(null);
  const [history, setHistory] = useState<HistoryItem[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [hasKey, setHasKey] = useState<boolean>(true);

  // Check for API key on mount per guidelines
  useEffect(() => {
    const checkKey = async () => {
      if (window.aistudio) {
        const selected = await window.aistudio.hasSelectedApiKey();
        setHasKey(selected);
      }
    };
    checkKey();
  }, []);

  const handleOpenKeySelector = async () => {
    if (window.aistudio) {
      await window.aistudio.openSelectKey();
      // Assume success per instructions: "you MUST assume the key selection was successful after triggering openSelectKey() and proceed"
      setHasKey(true);
    }
  };

  // Auto-generate prompt when config changes
  useEffect(() => {
    const prompt = `A professional editorial photography of a ${config.gender} model with ${config.bodyShape} body type. The model should have the exact facial features from the reference images. Camera positioned at ${config.perspective}, captured with ${config.lighting} lighting. The model is posing naturally. THE BACKGROUND IS PURE WHITE, clean and minimalist studio setting. Highly detailed, photorealistic, ${config.imageSize} resolution.`;
    setGeneratedPrompt(prompt);
