                <div className="text-center p-8">
                  <div className="w-16 h-16 bg-blue-50 text-blue-300 rounded-full flex items-center justify-center mx-auto mb-4">
                    <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
                    </svg>
                  </div>
                  <p className="text-gray-400 font-medium italic">Your generated portrait will appear here</p>
                </div>
              )}
              {loading && (
                <div className="absolute inset-0 bg-white/60 backdrop-blur-sm flex flex-col items-center justify-center">
                  <div className="flex gap-2 mb-4">
                    <div className="w-3 h-3 bg-blue-600 rounded-full animate-bounce delay-100"></div>
                    <div className="w-3 h-3 bg-blue-600 rounded-full animate-bounce delay-200"></div>
                    <div className="w-3 h-3 bg-blue-600 rounded-full animate-bounce delay-300"></div>
                  </div>
                  <p className="text-blue-800 font-bold animate-pulse">Capturing the light...</p>
                  <p className="text-xs text-blue-600 mt-1">Applying skin textures and micro-expressions</p>
                </div>
              )}
            </div>
          </div>

          {history.length > 0 && (
            <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-200">
              <h2 className="text-xl font-bold mb-4">Previous Generations</h2>
              <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-4">
                {history.map(item => (
                  <div 
                    key={item.id} 
                    className="aspect-square rounded-xl overflow-hidden cursor-pointer border border-gray-100 hover:ring-4 hover:ring-blue-100 transition shadow-sm"
                    onClick={() => setResult(item)}
                  >
                    <img src={item.imageUrl} alt="History Item" className="w-full h-full object-cover" />
                  </div>
                ))}
              </div>
            </div>
          )}
        </section>
      </main>

      <footer className="max-w-6xl mx-auto mt-12 pt-8 border-t border-gray-200 text-center text-gray-500 text-sm">
        Built with Gemini 3 Pro Vision • Ultra-Realistic Headshot Generation
      </footer>
    </div>
  );
};

