import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { ModelConfig, UploadedImage } from "./types";

export const generateModelImage = async (
  images: UploadedImage[],
  config: ModelConfig,
  customPrompt: string
): Promise<{ imageUrl: string }> => {
  // Always create a new instance right before call per instructions
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

  // Prepare image parts for the multimodal request
  const imageParts = images.map(img => ({
    inlineData: {
      mimeType: img.mimeType,
      data: img.base64.split(',')[1], // Strip data:image/png;base64,
    },
  }));

  // Core behavioral instructions for the subject extraction and background
  const systemInstruction = `ACT AS AN EXPERT STUDIO PHOTOGRAPHER. 
  YOUR TASK: Generate a NEW professional studio photograph based on the provided facial references.
  SUBJECT IDENTITY: Precisely extract facial features and unique identity markers from ALL reference photos. Replicate this identity perfectly in the generated subject.
  ENVIRONMENT: The background MUST BE ABSOLUTELY PURE WHITE (#FFFFFF), perfectly clean, with no shadows, floor transitions, or gradients.
  TECHNICAL REQUIREMENTS: Photorealistic, 8k resolution, highly detailed skin pores, realistic eyes, professional studio lighting.
  OUTPUT: You MUST return a generated image.`;

  // Specific configuration prompt
  const userPrompt = `Generate a high-quality editorial photograph of the model in the reference images:
  - Gender: ${config.gender}
  - Body Type: ${config.bodyShape}
  - Perspective: ${config.perspective}
  - Lighting: ${config.lighting}

  Scene Details: ${customPrompt}`;

  try {
    const response: GenerateContentResponse = await ai.models.generateContent({
      model: 'gemini-3-pro-image-preview',
      contents: {
        parts: [
          ...imageParts,
          { text: userPrompt }
        ]
      },
      config: {
        systemInstruction,
        imageConfig: {
          aspectRatio: config.aspectRatio,
          imageSize: config.imageSize,
        },
      },
    });

    let refusalText = "";

    // Find the image part in candidates
    const parts = response.candidates?.[0]?.content?.parts || [];
    for (const part of parts) {
      if (part.inlineData) {
        return {
          imageUrl: `data:image/png;base64,${part.inlineData.data}`,
        };
      }
      if (part.text) {
        refusalText += part.text;
      }
    }

    if (refusalText) {
      throw new Error(`Model Refusal: ${refusalText}`);
    }

    throw new Error('The model did not generate an image.');
  } catch (error: any) {
    console.error('Gemini Generation Error:', error);

    // Reset key selection if the specific error occurs
    if (error.message?.includes("Requested entity was not found.")) {
      throw new Error("API_KEY_RESET");
    }

    throw error;
  }
};
